uniform float decay; // 0.8 0.995 0.95
uniform float drift; // 0 4 1

void mainImage( out vec4 o, in vec2 f )
{
    vec2 uv = f / iResolution.xy;
    vec2 c = uv - 0.5;
    vec2 prevUv = 0.5 + c * ( 1.0 - 0.004 * drift ) + 0.002 * drift * vec2( sin( iTime ), cos( iTime * 0.7 ) );
    vec4 prev = texture( iChannel0, prevUv ) * decay;
    vec4 src = texture( iChannel1, uv );
    o = max( prev, src );
    if( iFrame == 0 ) o = src;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    fragColor = texture( iChannel0, fragCoord / iResolution.xy );
}
